import{_ as p,a0 as d,w as l,s as e,ao as s,I as o,a1 as r,A as a,x as n}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const I=JSON.parse('{"title":"在Linux上安裝Android 4.4 KitKat來玩玩喜愛的遊戲和應用 | LCTT x X-CMD","titleTemplate":false,"description":"在Linux上安裝Android 4.4 KitKat來玩玩喜愛的遊戲和應用 | LCTT (201408) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"在Linux上安裝Android 4.4 KitKat來玩玩喜愛的遊戲和應用 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"在Linux上安裝Android 4.4 KitKat來玩玩喜愛的遊戲和應用 | LCTT (201408) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201408/20140716 Install Android 4.4 KitKat to Run Favourite Games and Applications in Linux","title":"在Linux上安裝Android 4.4 KitKat來玩玩喜愛的遊戲和應用","tag":"201408","desc":""},"relativePath":"201408/20140716 Install Android 4.4 KitKat to Run Favourite Games and Applications in Linux.md","filePath":"[post].md"}'),g={name:"201408/20140716 Install Android 4.4 KitKat to Run Favourite Games and Applications in Linux.md"};function u(w,t,m,K,c,A){const i=d("Link");return l(),e("div",null,[t[19]||(t[19]=s(`<h1 id="在linux上安裝android-4-4-kitkat來玩玩喜愛的遊戲和應用" tabindex="-1">在Linux上安裝Android 4.4 KitKat來玩玩喜愛的遊戲和應用 <a class="header-anchor" href="#在linux上安裝android-4-4-kitkat來玩玩喜愛的遊戲和應用" aria-label="Permalink to “在Linux上安裝Android 4.4 KitKat來玩玩喜愛的遊戲和應用”">​</a></h1><p><strong>Android (x86)</strong>項目致力於移植Android系統到X86處理器上，使用户可以更容易的在任何電腦上安裝Android。他們通過使用android源碼，增加補丁來使Android能夠在X86處理器，筆記本電腦和平板電腦下工作。</p><p><img src="http://www.tecmint.com/wp-content/uploads/2014/07/Install-Android-4.4-KitKat.jpg" alt="Install Android 4.4 KitKat in Linux"> 在Linux安裝Android 4.4 KitKat</p><p>前一段時間，項目組發佈了最新的“Android KitKat 4.4 RC2”，下面，我將説明如何在VirtualBox上安裝，不過有一個小問題，安裝完成Android後鼠標指針不工作了，我猜，如果你根據本教程將它安裝成主系統，這個鼠標應該可以工作，否則我們只能使用鍵盤了。</p><h3 id="第一步-在linux上安裝virtualbox" tabindex="-1">第一步: 在linux上安裝VirtualBox <a class="header-anchor" href="#第一步-在linux上安裝virtualbox" aria-label="Permalink to “第一步: 在linux上安裝VirtualBox”">​</a></h3><p><strong>1.</strong> 大多數的Linux發行版中，官方源都有VirtualBox，例如在Ubuntu中安裝</p><pre><code>$ sudo apt-get install virtualbox
</code></pre><p>其他的Linux發行版，像<strong>RHEL, CentOS and Fedora</strong>,請參考下面文章來安裝VirtualBox</p>`,8)),o("ul",null,[o("li",null,[r(i,{href:"http://www.tecmint.com/install-virtualbox-on-redhat-centos-fedora/"},{default:a(()=>[...t[0]||(t[0]=[n("Install VirtualBox in RHEL, CentOS and Fedora",-1)])]),_:1})])]),t[20]||(t[20]=o("h3",{id:"第二步-下載並在virtualbox中安裝android-4-4-kitkat",tabindex:"-1"},[n("第二步: 下載並在VirtualBox中安裝Android 4.4 kitkat "),o("a",{class:"header-anchor",href:"#第二步-下載並在virtualbox中安裝android-4-4-kitkat","aria-label":"Permalink to “第二步: 下載並在VirtualBox中安裝Android 4.4 kitkat”"},"​")],-1)),o("p",null,[t[2]||(t[2]=o("strong",null,"2.",-1)),t[3]||(t[3]=n(" 這步挺簡單的，只是需要去",-1)),r(i,{href:"http://sourceforge.net/projects/android-x86/"},{default:a(()=>[...t[1]||(t[1]=[n("androud Sourceforge.net",-1)])]),_:1}),t[4]||(t[4]=n("項目下載 ",-1)),t[5]||(t[5]=o("strong",null,"Android 4.4 x86 Kit Kat",-1)),t[6]||(t[6]=n("文件",-1))]),t[21]||(t[21]=s('<p><strong>3.</strong> 要想安裝<strong>Android 4.4 kitkat</strong>，首先，你需要啓動剛剛下載.iso文件，打開 <strong>VirtualBox</strong>,創建一個新的虛擬機，然後按照下面圖片設置：</p><p><img src="http://www.tecmint.com/wp-content/uploads/2014/07/Install-Android-Kit-Kat-in-Linux-01.png" alt="Create New Virtual Machine"> 創建新的虛擬機</p><p><strong>4.</strong> 接下來，它會詢問你新設備的內存大小，Android 4.4 kikat需要1G內存才能完美運行，但是由於我的電腦只有1G內存，我只能選擇512MB。</p><p><img src="http://www.tecmint.com/wp-content/uploads/2014/07/Install-Android-Kit-Kat-in-Linux-02.png" alt="Set Memory to New Machine"> 設置內存</p><p><strong>5.</strong> 選擇“現在創建虛擬硬盤”（“Create a virtual hard drive now”）來創建一個新的硬盤。</p><p><img src="http://www.tecmint.com/wp-content/uploads/2014/07/Install-Android-Kit-Kat-in-Linux-03.png" alt="Create Virtual Hard Drive"> 創建虛擬硬盤</p><p><strong>6.</strong> 它現在會詢問你新虛擬硬盤的類型，選擇<strong>VDI</strong></p><p><img src="http://www.tecmint.com/wp-content/uploads/2014/07/Install-Android-Kit-Kat-in-Linux-04.png" alt="Select Hard Drive Type"> 選擇硬盤驅動類型</p><p><img src="http://www.tecmint.com/wp-content/uploads/2014/07/Install-Android-Kit-Kat-in-Linux-05.png" alt="Select Storage Type"> 選擇存儲方式</p><p><strong>7.</strong> 現在設置虛擬硬盤大小，你可以按照你的所需來設置任何大小，但是除了將來安裝Apps所用的空間，至少需要<strong>4G</strong>來保證系統正確安裝。</p><p><img src="http://www.tecmint.com/wp-content/uploads/2014/07/Install-Android-Kit-Kat-in-Linux-32.png" alt="Set Size for Virtual Drive"> 設置虛擬硬盤大小</p><p><strong>8.</strong> 現在你的新虛擬設備創建好了，可以啓動下載的<strong>.iso</strong>文件了，從左邊的列表選擇創建的虛擬機，點擊<strong>設置</strong> -&gt; <strong>存儲</strong> ，如下圖，選擇<strong>android 4.4 kitkat RC2</strong>的鏡像文件。</p><p><img src="http://www.tecmint.com/wp-content/uploads/2014/07/Install-Android-Kit-Kat-in-Linux-06.png" alt="Select Android KitKat ISO"> 選擇Android KitKat ISO</p><p><strong>9.</strong> 點擊<strong>OK</strong>, 打開機器,啓動.iso鏡像, 選擇 “<strong>安裝</strong>” 開始在虛擬機上安裝系統.</p><p><img src="http://www.tecmint.com/wp-content/uploads/2014/07/Install-Android-Kit-Kat-in-Linux-07.png" alt="Select to Install Android Kit Kat"> 選擇安裝Android Kit Kat</p><p><strong>10.</strong> 請選擇一個分區來安裝Android-x86</p><p><img src="http://www.tecmint.com/wp-content/uploads/2014/07/Install-Android-Kit-Kat-in-Linux-08.png" alt="Select Partition Drive"> 選擇 Partition Drive</p><p><strong>11.</strong> 如下圖，你可以看見cfdisk界面，cfdisk是一個分區工具，我們將要使用它來創建一個新的硬盤分區，用來安裝Android 4.4，現在，點擊 “<strong>New</strong>”</p><p><img src="http://www.tecmint.com/wp-content/uploads/2014/07/Install-Android-Kit-Kat-in-Linux-09.png" alt="Create New Partition"> 創建新分區</p><p><strong>12.</strong> 選擇“<strong>Primary</strong>”作為分區類型</p><p><img src="http://www.tecmint.com/wp-content/uploads/2014/07/Install-Android-Kit-Kat-in-Linux-10.png" alt="Choose Primary Partition"> 選擇主分區</p><p><strong>13.</strong> 接下來，設置分區大小</p><p><img src="http://www.tecmint.com/wp-content/uploads/2014/07/Install-Android-Kit-Kat-in-Linux-11.png" alt="Select Size of Partition"> 設置分區大小</p><p><strong>14.</strong> 現在我們必須給硬盤創建新的引導使其能夠寫入新的分區表，點擊“<strong>Bootable</strong>”給引導標記新的分區，你不會注意到有任何變化，但是引導標記將會自己給選中分區。</p><p><img src="http://www.tecmint.com/wp-content/uploads/2014/07/Install-Android-Kit-Kat-in-Linux-12.png" alt="Make Partition Bootable"> 製作分區引導</p><p><strong>15.</strong> 完成之後，點擊“<strong>Write</strong>”對硬盤寫入新的分區。</p><p><img src="http://www.tecmint.com/wp-content/uploads/2014/07/Install-Android-Kit-Kat-in-Linux-13.png" alt="Apply Changes to Partition"> 應用新分區</p><p><strong>16.</strong> 它會詢問你是否確認，輸入“<strong>yes</strong>”並點擊<strong>Enter</strong></p><p><img src="http://www.tecmint.com/wp-content/uploads/2014/07/Install-Android-Kit-Kat-in-Linux-14.png" alt="Confirm Partition Changes"> 確認分區改變</p><p><strong>17.</strong> 現在我們的新硬盤已經創建，點擊 <strong>Quit</strong> 你就可以看來類似下圖的顯示，選中剛剛創建的用來安裝Android 的分區，點擊<strong>Enter</strong></p><p><img src="http://www.tecmint.com/wp-content/uploads/2014/07/Install-Android-Kit-Kat-in-Linux-15.png" alt="Choose Partition to Install Android"> 選擇分區來安裝Android</p><p><strong>18.</strong> 選擇“<strong>ext3</strong>”作為硬盤文件系統並格式化</p><p><img src="http://www.tecmint.com/wp-content/uploads/2014/07/Install-Android-Kit-Kat-in-Linux-16.png" alt="Select Ext3 Partition Type"> 選擇Ext3分區類型</p><p><img src="http://www.tecmint.com/wp-content/uploads/2014/07/Install-Android-Kit-Kat-in-Linux-17.png" alt="Format Partition"> 格式化分區</p><p><strong>19.</strong> 它將會詢問你是否需要安裝GRUB啓動器，當然選擇<strong>Yes</strong>，如果不這樣，你將不能啓動新系統，所以選擇<strong>Yes</strong>並點擊<strong>Enter</strong></p><p><img src="http://www.tecmint.com/wp-content/uploads/2014/07/Install-Android-Kit-Kat-in-Linux-18.png" alt="Install Boot Loader GRUB"> 安裝啓動加載器 GRUB</p><p><strong>20.</strong> 最後，它會問你是否設置<strong>/system</strong>分區能寫入，選擇<strong>yes</strong>，它會在安裝完系統後幫助你減少很多麻煩。</p><p><img src="http://www.tecmint.com/wp-content/uploads/2014/07/Install-Android-Kit-Kat-in-Linux-19.png" alt="Make Partition Writeable"> 使分區能寫入</p><p><strong>21.</strong> 安裝將會開始它的任務，安裝器結束工作後，選擇重啓，在我做測試的時候，“Run-Android x86”不起作用，所以你不得不重啓。</p><p><img src="http://www.tecmint.com/wp-content/uploads/2014/07/Install-Android-Kit-Kat-in-Linux-20.png" alt="Android Kit Kat Installation"> Android Kit kat 安裝完成</p><p><strong>22.</strong> 我們已經完成安裝<strong>Android 4.4 KitKat RC2</strong>，問題是VirtualBox將會繼續加載<strong>.iso</strong>鏡像文件而不是從虛擬硬盤驅動啓動，所以為了修正這個問題，選擇<strong>設置</strong> -&gt; <strong>存儲</strong> -&gt;移除iso文件</p><p><img src="http://www.tecmint.com/wp-content/uploads/2014/07/Install-Android-Kit-Kat-in-Linux-21.png" alt="Remove Android Kit Kat Image"> 移除Android Kit Kat 鏡像</p><p><strong>23.</strong> 你可以啓動你的虛擬設備，運行你的Android系統了</p><p><img src="http://www.tecmint.com/wp-content/uploads/2014/07/Install-Android-Kit-Kat-in-Linux-23.png" alt="Start Android Kit Kat System"> 啓動Android Kit Kat 系統</p><p><img src="http://www.tecmint.com/wp-content/uploads/2014/07/Install-Android-Kit-Kat-in-Linux-24.png" alt="Android Splash Screen"> Android標誌界面</p><p><strong>24.</strong> 使用<strong>Android</strong>之前，你需要完成一個嚮導來進行配置。你會看見如下屏幕，現在的問題是，鼠標不能在<strong>android 4.4 kitkat</strong>工作，這意味着我們需要展示我們高超的鍵盤試用技巧了。首先，選擇語言，你需要使用鍵盤<strong>上</strong>鍵和<strong>下</strong>鍵，進行到下一步，敲擊<strong>右</strong>鍵移動光標，選擇<strong>Enter</strong></p><p><img src="http://www.tecmint.com/wp-content/uploads/2014/07/Install-Android-Kit-Kat-in-Linux-31.png" alt="Android Welcome Screen"> Android 歡迎界面</p><p><img src="http://www.tecmint.com/wp-content/uploads/2014/07/Install-Android-Kit-Kat-in-Linux-25.png" alt="Select WiFi Network"> 選擇WiFi網絡</p><p><img src="http://www.tecmint.com/wp-content/uploads/2014/07/Install-Android-Kit-Kat-in-Linux-26.png" alt="Create Android Google Account"> 創建Android Google賬户</p><p><img src="http://www.tecmint.com/wp-content/uploads/2014/07/Install-Android-Kit-Kat-in-Linux-27.png" alt="Sign in Google Account"> 註冊Google賬户</p><p><img src="http://www.tecmint.com/wp-content/uploads/2014/07/Install-Android-Kit-Kat-in-Linux-28.png" alt="Set Date and Time"> 設置日期和時間</p><p><img src="http://www.tecmint.com/wp-content/uploads/2014/07/Install-Android-Kit-Kat-in-Linux-29.png" alt="Enter Your Details"> 輸入你的信息</p><p><img src="http://www.tecmint.com/wp-content/uploads/2014/07/Install-Android-Kit-Kat-in-Linux-30.jpeg" alt="Android 4.4 Kit Kat Home Screen"> Android 4.4 Kit Kat 主界面</p><p>如果你沒有智能手機而又想輕鬆使用<strong>Play Store</strong>apps，那麼安裝 <strong>Android x86</strong>是個不錯的選擇。你曾經嘗試過安裝android x86嗎？結果怎樣呢？你有沒有想過android可以成為一個目標指向桌面功能的<strong>真正操作系統</strong>？</p><hr><p><img src="http://1.gravatar.com/avatar/1374d0df45065e405e1b059d2fca04ff?s=80&amp;d=blank&amp;r=G" alt=""></p>',56)),o("p",null,[r(i,{href:"http://www.tecmint.com/"},{default:a(()=>[...t[7]||(t[7]=[n("Hanny Helal",-1)])]),_:1})]),t[22]||(t[22]=o("p",null,"自2010年起，成為Linux和自由軟件用户，致力於多個自由軟件項目。",-1)),t[23]||(t[23]=o("hr",null,null,-1)),o("p",null,[t[9]||(t[9]=n("via: ",-1)),r(i,{href:"http://www.tecmint.com/install-android-kitkat-in-linux/"},{default:a(()=>[...t[8]||(t[8]=[n("http://www.tecmint.com/install-android-kitkat-in-linux/",-1)])]),_:1})]),o("p",null,[t[12]||(t[12]=n("譯者：",-1)),r(i,{href:"http://www.vicyu.net"},{default:a(()=>[...t[10]||(t[10]=[n("Vic___",-1)])]),_:1}),t[13]||(t[13]=n(" 校對：",-1)),r(i,{href:"https://github.com/carolinewuyan"},{default:a(()=>[...t[11]||(t[11]=[n("Caroline",-1)])]),_:1})]),o("p",null,[t[16]||(t[16]=n("本文由 ",-1)),r(i,{href:"https://github.com/LCTT/TranslateProject"},{default:a(()=>[...t[14]||(t[14]=[n("LCTT",-1)])]),_:1}),t[17]||(t[17]=n(" 原創翻譯，",-1)),r(i,{href:"http://linux.cn/"},{default:a(()=>[...t[15]||(t[15]=[n("Linux中國",-1)])]),_:1}),t[18]||(t[18]=n(" 榮譽推出",-1))])])}const f=p(g,[["render",u]]);export{I as __pageData,f as default};
